#include <iostream>

int main() {
    int price = 100;
    int count = 3;
    int discount = 10;
    int subtotal = price * count;
    int saving = subtotal * discount / 100;
    int total = subtotal - saving;
    std::cout << subtotal << ' ' << saving << ' ' << total << '\n';
    return 0;
}

